<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { CatalogosCuentaTesoreria, CuentaTesoreria, CuentaTesoreriaPayload } from '../interfaces/cuenta-tesoreria.interface'
import { cambiarEstadoCuentaTesoreria, eliminarCuentaTesoreria, guardarCuentaTesoreria, listarCuentasTesoreria, obtenerCatalogosCuentaTesoreria, obtenerCuentaTesoreria } from '../services/cuenta-tesoreria'
const emptyCatalogs = (): CatalogosCuentaTesoreria => ({ cuentas_contables: [], conceptos: [], fuentes: [], monedas: [], bancos: [] })
const emptyForm = (): CuentaTesoreriaPayload => ({ cuenta_contable_id: 0, codigo_concepto: 0, numero_cuenta_bancaria: '', correlativo_cheque: '', moneda_id: 0, banco_id: 0, fuente_financiamiento_id: 0 })
const rows = ref<CuentaTesoreria[]>([]), catalogs = ref(emptyCatalogs()), search = ref(''), loading = ref(false), error = ref(''), success = ref(''), showForm = ref(false), editing = ref<number | null>(null)
const form = reactive(emptyForm())
const message = (e: unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
async function load() { loading.value = true; error.value = ''; try { rows.value = await listarCuentasTesoreria(search.value) } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function ensureCatalogs() { if (!catalogs.value.cuentas_contables.length) catalogs.value = await obtenerCatalogosCuentaTesoreria() }
async function create() { loading.value = true; try { await ensureCatalogs(); editing.value = null; Object.assign(form, emptyForm()); showForm.value = true } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function edit(item: CuentaTesoreria) { loading.value = true; try { const [value] = await Promise.all([obtenerCuentaTesoreria(item.id), ensureCatalogs()]); editing.value = value.id; Object.assign(form, { cuenta_contable_id: value.cuenta_contable_id, codigo_concepto: value.codigo_concepto, numero_cuenta_bancaria: value.numero_cuenta_bancaria, correlativo_cheque: value.correlativo_cheque || '', moneda_id: value.moneda_id, banco_id: value.banco_id, fuente_financiamiento_id: value.fuente_financiamiento_id }); showForm.value = true } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function save() { loading.value = true; error.value = ''; try { await guardarCuentaTesoreria(editing.value, { ...form }); success.value = `Cuenta de tesorería ${editing.value ? 'actualizada' : 'registrada'} correctamente.`; showForm.value = false; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function toggle(item: CuentaTesoreria) { const action = item.activo ? 'desactivar' : 'activar'; if (!confirm(`¿Desea ${action} la cuenta bancaria ${item.numero_cuenta_bancaria}?`)) return; loading.value = true; try { await cambiarEstadoCuentaTesoreria(item.id); success.value = `Cuenta ${item.activo ? 'desactivada' : 'activada'} correctamente.`; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function remove(item: CuentaTesoreria) { if (!confirm(`¿Eliminar la cuenta de tesorería ${item.numero_cuenta_bancaria}?`)) return; loading.value = true; try { await eliminarCuentaTesoreria(item.id); success.value = 'Cuenta de tesorería eliminada correctamente.'; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
function clear() { search.value = ''; load() }
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Cuentas de tesorería</nav><header class="hero"><div class="mark">CT</div><div><small>MIA · FINANZAS · MAESTROS</small><h1>Cuentas de tesorería</h1><p>Configuración bancaria y contable de las cuentas utilizadas por tesorería.</p></div><strong>{{rows.length}} registros</strong><button @click="create">+ Nueva cuenta</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load"><input v-model.trim="search" placeholder="Cuenta, banco, concepto o fuente de financiamiento"><button>Buscar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron cuentas de tesorería.</div><div v-else class="scroll"><table><thead><tr><th>Cuenta contable</th><th>Cuenta bancaria</th><th>Banco / moneda</th><th>Concepto</th><th>Fuente</th><th>Cheque</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.cuenta_contable?.cta_contable}}</b><small>{{item.cuenta_contable?.descripcion}}</small></td><td><b>{{item.numero_cuenta_bancaria}}</b></td><td>{{item.banco?.nombre||item.banco?.descripcion}}<small>{{item.moneda?.simbolo}} · {{item.moneda?.nombre}}</small></td><td>{{item.concepto_cuenta?.nombre}}</td><td>{{item.fuente_financiamiento?.nombre}}<small>{{item.fuente_financiamiento?.descripcion}}</small></td><td>{{item.correlativo_cheque||'-'}}</td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVA':'INACTIVA'}}</span></td><td class="actions"><button class="edit" @click="edit(item)">Editar</button><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Desactivar':'Activar'}}</button><button class="delete" @click="remove(item)">Eliminar</button></td></tr></tbody></table></div></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar':'Registrar'}} cuenta de tesorería</h2></div><button type="button" @click="showForm=false">×</button></header><label>Cuenta contable<select v-model.number="form.cuenta_contable_id" required><option :value="0" disabled>Seleccione</option><option v-for="x in catalogs.cuentas_contables" :key="x.id" :value="x.id">{{x.cta_contable}} · {{x.descripcion}}</option></select></label><div class="twocol"><label>Número de cuenta bancaria<input v-model.trim="form.numero_cuenta_bancaria" maxlength="50" required></label><label>Correlativo de cheque<input v-model.trim="form.correlativo_cheque" maxlength="50"></label></div><div class="twocol"><label>Banco<select v-model.number="form.banco_id" required><option :value="0" disabled>Seleccione</option><option v-for="x in catalogs.bancos" :key="x.id" :value="x.id">{{x.nombre||x.descripcion}}</option></select></label><label>Moneda<select v-model.number="form.moneda_id" required><option :value="0" disabled>Seleccione</option><option v-for="x in catalogs.monedas" :key="x.id" :value="x.id">{{x.nombre}} {{x.simbolo}}</option></select></label></div><label>Concepto de cuenta<select v-model.number="form.codigo_concepto" required><option :value="0" disabled>Seleccione</option><option v-for="x in catalogs.conceptos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Fuente de financiamiento<select v-model.number="form.fuente_financiamiento_id" required><option :value="0" disabled>Seleccione</option><option v-for="x in catalogs.fuentes" :key="x.id" :value="x.id">{{x.nombre}} · {{x.descripcion}}</option></select></label><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div></div></template>
<style scoped>
