auto}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.dialog label{display:grid;gap:5px;margin:10px 0;color:#5d7078;font-size:.52rem;font-weight:700}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:10px}.dialog footer{display:flex;justify-content:center;gap:8px;margin-top:15px}@media(max-width:650px){.filters,.twocol{grid-template-columns:1fr}.hero{flex-wrap:wrap}.mark{display:none}}
